    if urgency >= 6:
        bid = max(110.0, high_prev + 3.0)
    elif urgency >= 4:
        if high_prev >= 120:
            bid = 108.0
        else:
            bid = max(82.0, avg_prev * 0.78 + 6.0)
    elif urgency >= 2:
        if dangerous_prev and supply >= 20 and hp > 4:
            bid = 28.0
        else:
            bid = max(42.0, min(78.0, avg_prev * 0.55 + 4.0))
    else:
        if high_prev >= 110:
            bid = 18.0 if supply >= 19 else 32.0
        else:
            bid = 26.0 if supply >= 20 else 38.0

